package com.coworkhub.controller;
import com.coworkhub.repository.UserAccountRepository;import com.coworkhub.security.JwtService;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.util.*;import java.time.Instant;
@RestController @RequestMapping("/auth")public class AuthController {private final UserAccountRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserAccountRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}record Login(String username,String password){} @PostMapping("/login")public ResponseEntity<?> login(@RequestBody Login in){if(in==null||in.username()==null||in.password()==null)return ResponseEntity.badRequest().body(Map.of("error","Usuario y contraseña obligatorios","codigo","VALIDATION"));var user=users.findByUsername(in.username()).orElse(null);if(user==null||!encoder.matches(in.password(),user.password))return ResponseEntity.status(401).body(Map.of("error","Credenciales inválidas","codigo","AUTH","timestamp",Instant.now().toString()));return ResponseEntity.ok(Map.of("token",jwt.generate(user.username,user.role.name(),user.member==null?null:user.member.id),"tipo","Bearer","expiresIn",3600));} @GetMapping("/perfil") public Map<String,Object> profile(org.springframework.security.core.Authentication a){var u=users.findByUsername(a.getName()).orElseThrow();return Map.of("usuario",u.username,"rol",u.role,"miembroId",u.member==null?0:u.member.id);} }
